bool pmq_enqueue(PMQ *q, void *payload) {
  uint64_t h = atomic_fetch_add_explicit(&q->head, 1, memory_order_relaxed);
  Slot *s = &q->slots[h & (N-1)];
  if (s->seq != h) return false;
  memcpy(s->payload, payload, PAYLOAD_SIZE);
  atomic_store_explicit(&s->seq, h+1, memory_order_release);
  // flush payload and seq to NVM, ensure visibility
